\tdplotsetmaincoords{70}{300}
\begin{tikzpicture}[tdplot_main_coords,scale=0.9]
\coordinate (O) at (0,0,0);
\coordinate (X) at (3,0,0);
\coordinate (Y) at (0,3,0);
\coordinate (Z) at (0,0,3);
\coordinate (XY) at (3,3,0);
\coordinate (XZ) at (3,0,3);
\coordinate (YZ) at (0,3,3);
\coordinate (P) at (3,3,3);
\draw (XY)--(X) node[midway,above right,font=\scriptsize] {$10\text{ mm}$};
\draw[dashed] (XY) -- (Y);
\draw (XY)--(P);
\draw (O) -- (X) node[midway,below right,font=\scriptsize] {$10\text{ mm}$};
\draw[dashed] (O)--(Y);
\draw[dashed] (Y)--(YZ);
\draw (O) -- (Z);
\draw (X) -- (XZ);
\draw (Z) -- (XZ);
\draw (Z) -- (YZ);
\draw (XZ) -- (P);
\draw (YZ) -- (P);
\end{tikzpicture}
[/tikz]
This cube has edges of length $1$ cm, which is $10$ mm.
How many $\text{mm}^3$ are there in $1\text{ cm}^3$?

